import requests
import pickle
from pwn import *
import numpy as np

def download_pickle(url, filename):
    try:
        response = requests.get(url)
        response.raise_for_status()

        # Save the file
        with open(filename, 'wb') as f:
            f.write(response.content)

        # Try to load and validate the pickle
        with open(filename, 'rb') as f:
            data = pickle.load(f)

        # Get info about the data
        if isinstance(data, np.ndarray):
            info = f"Shape: {data.shape}, dtype: {data.dtype}"
        elif isinstance(data, list):
            info = f"Length: {len(data)}, type: list"
        else:
            info = f"Type: {type(data)}"

        return True, info
    except Exception as e:
        return False, str(e)

def main():
    base_url = "http://misc.chal.csaw.io:3000"

    # Check various endpoints
    endpoints = ['/', '/data', '/download', '/files', '/train', '/test']

    for endpoint in endpoints:
        log.info(f"Checking endpoint: {endpoint}")
        try:
            response = requests.get(f"{base_url}{endpoint}")
            print(f"Status: {response.status_code}")
            print(response.text)
            print("-" * 50)
        except Exception as e:
            log.failure(f"Error accessing {endpoint}: {e}")

    # Try to download the pickle files from potential locations
    files = ['X.pkl', 'y.pkl', 'X_test.pkl']
    possible_paths = ['/data', '/download', '/files', '/train', '/test', '']

    for path in possible_paths:
        for file in files:
            log.info(f"Trying to download {file} from {path}")
            url = f"{base_url}{path}/{file}"
            try:
                success, info = download_pickle(url, file)
                if success:
                    log.success(f"Successfully downloaded {file} from {path}: {info}")
            except:
                continue

if __name__ == "__main__":
    main()
